  'tpl.words.subsHelp': { en: 'It sets the {n} subtitle line under it, word by word on their own timing. Drag the block over the part of the narration you want big.', tr: 'Altındaki {n} altyazı satırını, kendi zamanlamasıyla kelime kelime dizer. Bloğu anlatımın büyük görmek istediğin kısmının üstüne sürükle.' },
  'tpl.words.subsHelpN': { en: 'It sets the {n} subtitle lines under it, word by word on their own timing. Drag the block over the part of the narration you want big.', tr: 'Altındaki {n} altyazı satırını, kendi zamanlamalarıyla kelime kelime dizer. Bloğu anlatımın büyük görmek istediğin kısmının üstüne sürükle.' },
  'tpl.words.noSubs': { en: 'No subtitles under it yet — make them (Subtitles panel), or use your own lines. Until then it shows the lines below.', tr: 'Altında henüz altyazı yok: üret (Altyazı paneli) ya da kendi satırlarını kullan. O zamana kadar aşağıdaki satırları gösterir.' },
  'tpl.ends': { en: 'Ends', tr: 'Bitiş' },
