  'tpl.leaves.fade': { en: 'Fades', tr: 'Solar' },
  'tpl.leaves.fade.hint': { en: 'It fades away, settling a touch smaller', tr: 'Biraz küçülerek solar' },
  'tpl.leaves.slide': { en: 'Slides away', tr: 'Kayar' },
