  'tpl.boxes.hub': { en: 'Hub', tr: 'Merkez' },
  'tpl.boxes.hub.hint': { en: 'The main box in the middle, the others either side; its light runs out to each', tr: 'Ana kutu ortada, ötekiler iki yanında; ışığı her birine doğru akar' },
  'tpl.boxes.flow': { en: 'Flow', tr: 'Akış' },
  'tpl.boxes.flow.hint': { en: 'The main box on the left leading into a column of boxes', tr: 'Soldaki ana kutu bir kutu sütununa bağlanır' },
  'tpl.boxes.chain': { en: 'Chain', tr: 'Zincir' },
  'tpl.boxes.chain.hint': { en: 'Box to box in a row: each lights the next', tr: 'Sıra hâlinde kutudan kutuya: her biri sonrakini yakar' },
  'tpl.boxes.help.main': { en: 'Each box lights at its own moment: set it below (the crosshair puts it at the playhead), or drag its yellow mark on the G lane. The light leaves the main box a moment before and runs along the line into it.', tr: 'Her kutu kendi anında yanar: aşağıdan ayarla (artı işareti oynatma çizgisine koyar) ya da G şeridindeki sarı işaretini sürükle. Işık bir an önce ana kutudan çıkar ve çizgi boyunca kutuya akar.' },
  'tpl.boxes.help.chain': { en: 'Each box lights at its own moment: set it below (the crosshair puts it at the playhead), or drag its yellow mark on the G lane. The light leaves the box before it a moment before and runs along the line into it.', tr: 'Her kutu kendi anında yanar: aşağıdan ayarla (artı işareti oynatma çizgisine koyar) ya da G şeridindeki sarı işaretini sürükle. Işık bir an önce önceki kutudan çıkar ve çizgi boyunca kutuya akar.' },
  'tpl.boxes.lights': { en: 'Lights at', tr: 'Yanma anı' },
