  'tpl.boxes.lightHere': { en: 'Light it at the playhead', tr: 'Oynatma çizgisinde yak' },
  'tpl.boxes.even': { en: 'Back to the even spacing', tr: 'Eşit aralığa dön' },
  'tpl.cards.dealt': { en: 'Dealt', tr: 'Dağıtım' },
  'tpl.cards.down': { en: 'Face down', tr: 'Kapalı' },
  'tpl.cards.down.hint': { en: 'Face down in a row, then turned over one by one', tr: 'Sıra hâlinde kapalı, sonra birer birer açılır' },
  'tpl.cards.up': { en: 'Face up', tr: 'Açık' },
