  'tpl.screen.chat': { en: 'Chat', tr: 'Sohbet' },
  'tpl.screen.notes': { en: 'Notes', tr: 'Notlar' },
  'tpl.screen.search': { en: 'Search', tr: 'Arama' },
  'tpl.screen.terminal.help': { en: 'Each line is typed at the prompt; its note is printed as the output after Enter.', tr: 'Her satır komut satırına yazılır; notu Enter’dan sonra çıktı olarak basılır.' },
  'tpl.screen.browser.help': { en: 'Each line is an address typed into the bar; on Enter the page loads with its note as the headline (and the line’s picture, if it has one).', tr: 'Her satır adres çubuğuna yazılan bir adrestir; Enter’da sayfa, notu başlık olarak (ve varsa satırın resmiyle) yüklenir.' },
  'tpl.screen.chat.help': { en: 'Each line is a message typed and sent; its reply comes back after the typing dots, when you set it (seconds after sending). Leave a message empty and fill only the reply to have them write first.', tr: 'Her satır yazılıp gönderilen bir iletidir; yanıtı, yazıyor noktalarından sonra, ayarladığın anda (gönderdikten kaç saniye sonra) gelir. Önce karşı taraf yazsın istersen iletiyi boş bırakıp yalnız yanıtı doldur.' },
  'tpl.screen.notes.help': { en: 'Each line is typed onto the page; its note goes under it in grey.', tr: 'Her satır sayfaya yazılır; notu altına gri olarak gelir.' },
  'tpl.screen.search.help': { en: 'Each line is a search; on Enter the box moves up and the results come in, the note as the top result.', tr: 'Her satır bir aramadır; Enter’da kutu yukarı çıkar ve sonuçlar gelir, not en üstteki sonuç olur.' },
  'tpl.screen.keyboard': { en: 'A US keyboard: letters, digits and the symbols on it are typed key by key (capitals and symbols with shift); the block’s length sets the pace.', tr: 'ABD klavyesi: harfler, rakamlar ve üstündeki simgeler tuş tuş yazılır (büyük harfler ve simgeler shift ile); bloğun uzunluğu tempoyu belirler.' },
  'tpl.quote.kind': { en: 'Kind', tr: 'Tür' },
  'tpl.quote.quote': { en: 'Quote', tr: 'Alıntı' },
  'tpl.quote.verse': { en: 'Verse', tr: 'Ayet' },
  'tpl.quote.from': { en: 'Comes in from', tr: 'Geldiği yön' },
  'tpl.quote.help.verse': { en: 'The text is the translation; the first reference line is where it is from (Bakara 2:286), its note the translation used. Add a second line with the original (Arabic) text and it is shown above, read in from the right.', tr: 'Yazı çeviridir; ilk kaynak satırı nereden olduğudur (Bakara 2:286), notu kullanılan çeviridir. Asıl (Arapça) metinle ikinci bir satır eklersen üstte, sağdan okunarak gösterilir.' },
  'tpl.quote.help.quote': { en: 'The text is the quote; the reference line is who said it, its note where.', tr: 'Yazı alıntıdır; kaynak satırı kimin söylediği, notu nerede söylediğidir.' },
  'tpl.cutout.title': { en: 'Title', tr: 'Başlık' },
  'tpl.cutout.help': { en: 'Each word becomes a paper cutout brought in from the edge. Change a word’s size below (100 = normal); Shuffle picks other papers and types; the hand-made look adds tape.', tr: 'Her kelime kenardan getirilen bir kâğıt kesiği olur. Bir kelimenin boyutunu aşağıdan değiştir (100 = olağan); Karıştır başka kâğıtlar ve yazılar seçer; el yapımı görünüm bant ekler.' },
  'tpl.cutout.shuffle': { en: 'Shuffle papers and type', tr: 'Kâğıtları ve yazıyı karıştır' },
  'tpl.place': { en: 'Place', tr: 'Yer' },
